function readJSON(k,f){try{return JSON.parse(localStorage.getItem(k)||"")||f}catch{return f}}function writeJSON(k,v){localStorage.setItem(k,JSON.stringify(v))}
function cloudError(error,fallback='操作失败，请稍后再试'){return error?.message||error?.error_description||fallback}
function cloudUid(user){return user?.id||user?.uid||user?.user_id||user?.sub}
function authUser(result){return result?.data?.user||result?.user||result?.data?.session?.user||result?.session?.user}
async function saveProfile(){if(!cloudDb||!state.user?.id)return;const payload={user_id:state.user.id,display_name:state.user.name||'学习者',english_level:state.user.level||'B1',bio:''};const {error}=await cloudDb.from('profiles').upsert(payload);if(error)throw error}
async function loadCloudUser(user){const id=cloudUid(user);if(!id)return null;let profile=null;if(cloudDb){const {data}=await cloudDb.from('profiles').select('*').eq('user_id',id).maybeSingle();profile=data}const local=readJSON(`${KEYS.legacy}:${id}`,{});state.user={id,email:user.email||local.email||'',name:profile?.display_name||local.name||user.user_metadata?.name||'学习者',level:profile?.english_level||local.level,age:local.age,goals:local.goals||[],ielts:local.ielts};return state.user}
async function bootstrapCloud(){if(!cloudAuth||!cloudDb){$('#login-message').textContent='云服务暂时没有加载，请刷新页面。';showScreen('auth-screen');return}try{const {data,error}=await cloudAuth.getSession();if(error)throw error;const user=data?.session?.user||data?.user;if(user){await loadCloudUser(user);state.cloudReady=true;if(state.user.level){setupDashboard();showScreen('dashboard-screen')}else{showScreen('onboarding-screen');updateStep()}}else showScreen('auth-screen')}catch(error){console.error(error);$('#login-message').textContent=cloudError(error,'无法连接腾讯云，请稍后刷新。');showScreen('auth-screen')}}
function showScreen(id){$$('.screen').forEach(x=>x.classList.toggle('is-active',x.id===id));scrollTo(0,0)}
function sound(type="tap"){try{state.audioContext||=new(AudioContext||webkitAudioContext)();const c=state.audioContext,o=c.createOscillator(),g=c.createGain(),[f,d]=({tap:[430,.035],next:[560,.06],success:[720,.11],error:[185,.1],complete:[880,.18]})[type]||[430,.035];o.frequency.setValueAtTime(f,c.currentTime);if(["success","complete"].includes(type))o.frequency.exponentialRampToValueAtTime(f*1.45,c.currentTime+d);o.type=type==="error"?"sawtooth":"sine";g.gain.setValueAtTime(.0001,c.currentTime);g.gain.exponentialRampToValueAtTime(.055,c.currentTime+.008);g.gain.exponentialRampToValueAtTime(.0001,c.currentTime+d);o.connect(g).connect(c.destination);o.start();o.stop(c.currentTime+d+.02)}catch{}}
function speak(w){if(!("speechSynthesis"in window))return;speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(w);u.lang="en-GB";u.rate=.82;speechSynthesis.speak(u)}
function switchAuth(tab){$$('.auth-tab').forEach(b=>b.classList.toggle('is-active',b.dataset.authTab===tab));$$('.auth-form').forEach(f=>f.classList.toggle('is-active',f.id===`${tab}-form`));sound('tap')}
