$('#register-form').addEventListener('submit',async e=>{e.preventDefault();const message=$('#register-message'),button=$('#register-submit'),name=$('#register-name').value.trim(),email=$('#register-email').value.trim().toLowerCase(),password=$('#register-password').value,code=$('#register-code').value.trim();button.disabled=true;try{if(!pendingRegistration){message.textContent='正在发送验证码…';const {data,error}=await cloudAuth.signUp({email,password});if(error)throw error;if(!data?.verifyOtp)throw new Error('验证码服务没有正确返回，请刷新后重试。');pendingRegistration={verify:data.verifyOtp,name,email};$('#otp-step').hidden=false;$('#register-code').required=true;$('#register-email').readOnly=true;$('#register-password').readOnly=true;button.innerHTML='完成注册 <span>→</span>';message.textContent=`验证码已发送到 ${email}，请查看收件箱。`;sound('next')}else{if(!code)throw new Error('请输入邮箱中的验证码。');message.textContent='正在验证并创建账号…';const {data,error}=await pendingRegistration.verify({token:code});if(error)throw error;const user=authUser({data})||data?.user;if(!user)throw new Error('注册成功但未取得登录信息，请直接登录。');state.user={id:cloudUid(user),email:pendingRegistration.email,name:pendingRegistration.name,goals:[]};await saveProfile();pendingRegistration=null;sound('complete');showScreen('onboarding-screen');updateStep()}}catch(error){message.textContent=cloudError(error);sound('error')}finally{button.disabled=false}});
$('#login-form').addEventListener('submit',async e=>{e.preventDefault();const message=$('#login-message'),button=$('#login-form button[type="submit"]'),email=$('#login-email').value.trim().toLowerCase(),password=$('#login-password').value;button.disabled=true;message.textContent='正在登录…';try{const {data,error}=await cloudAuth.signInWithPassword({email,password});if(error)throw error;const user=authUser({data})||data?.user;if(!user)throw new Error('没有取得账号信息，请重试。');await loadCloudUser(user);sound('next');if(state.user.level){setupDashboard();showScreen('dashboard-screen')}else{showScreen('onboarding-screen');updateStep()}}catch(error){message.textContent=cloudError(error,'邮箱或密码不正确。');sound('error')}finally{button.disabled=false}});
