function updateStep(){$$('.onboarding-step').forEach((e,i)=>e.classList.toggle('is-active',i===state.step));$('#step-label').textContent=`0${state.step+1} / 03`;$('#progress-bar').style.width=`${(state.step+1)/3*100}%`;$('#prev-step').classList.toggle('is-hidden',state.step===0);$('#next-step').innerHTML=state.step===2?'生成我的学习空间 <span>✦</span>':'继续 <span>→</span>'}
$('#next-step').addEventListener('click',async()=>{const c=$(`.onboarding-step[data-step="${state.step}"]`),r=$('input[required]',c);if(r&&!$(`input[name="${r.name}"]:checked`,c)){sound('error');c.animate([{transform:'translateX(-5px)'},{transform:'translateX(5px)'},{transform:'none'}],{duration:260});return}if(state.step<2){state.step++;sound('next');updateStep();return}const d=new FormData($('#profile-form'));state.user={...state.user,age:d.get('age'),level:d.get('level'),goals:d.getAll('goal'),ielts:$('#ielts-score').value};try{await updateAccount(state.user);sound('complete');setupDashboard();showScreen('dashboard-screen')}catch(error){alert(cloudError(error,'保存学习资料失败，请重试。'))}});
