function wrongbook(){return readJSON(`${KEYS.wrong}:${state.user?.email||'guest'}`,[])}function saveWrongbook(v){writeJSON(`${KEYS.wrong}:${state.user?.email||'guest'}`,v);updateWrongCount()}function updateWrongCount(){$('#wrong-count').textContent=wrongbook().length}
function setupDashboard(){const u=state.user||{name:'学习者',level:'B1',age:'18–24岁',goals:[]},l=u.level||'B1';$('#sidebar-name').textContent=u.name;$('#sidebar-avatar').textContent=(u.name||'L').slice(0,1).toUpperCase();$('#sidebar-level').textContent=`${l} · 学习中`;$('#greeting').textContent=`${greeting()}，${u.name}`;$('#level-pill').textContent=`${l} · ${levelName(l)}`;$('#article-level').textContent=`${l} · 约 6 分钟`;$('#profile-summary').textContent=`当前等级 ${l}${u.ielts?` · IELTS ${u.ielts}`:''}`;$('#plan-copy').textContent=`根据你的 ${l} 水平和“${(u.goals||[]).join('、')||'综合英语'}”目标，我们准备了约 25 分钟的内容。`;$('#today-date').textContent=new Intl.DateTimeFormat('zh-CN',{month:'long',day:'numeric',weekday:'long'}).format(new Date()).toUpperCase();updateWrongCount();const m=['chat','video','reading'];$('#recommendation-grid').innerHTML=levelContent[l].map((t,i)=>`<article class="recommend-card" data-icon="${['✦','▶','Aa'][i]}"><div class="card-top"><span>${['英语聊天','视频学习','英文阅读'][i]}</span><span class="time">${['8','6','11'][i]} 分钟</span></div><h4>${t}</h4><p>${['进入学习社区，与不同学习者练习英语。','短视频、关键词和跟读训练组合学习。','分级阅读与逐词精读已经合并，正文每个词都可以点击。'][i]}</p><button data-open="${m[i]}">开始 →</button></article>`).join('')}
function greeting(){const h=new Date().getHours();return h<11?'早上好':h<18?'下午好':'晚上好'}function levelName(l){return({A1:'BEGINNER',A2:'ELEMENTARY',B1:'INTERMEDIATE',B2:'UPPER INTERMEDIATE',C1:'ADVANCED',C2:'PROFICIENT'})[l]}
function openView(name){closeWord();$$('.view').forEach(v=>v.classList.remove('is-active'));$$('.nav-item').forEach(i=>i.classList.toggle('is-active',i.dataset.view===name));if(name==='home')$('#home-view').classList.add('is-active');else if(name==='intensive')$('#intensive-view').classList.add('is-active');else{$('#module-view').classList.add('is-active');renderModule(name)}$('.sidebar').classList.remove('is-open');scrollTo(0,0);sound('tap')}
document.addEventListener('click',e=>{const o=e.target.closest('[data-open]');if(o)openView(o.dataset.open)});$$('.nav-item').forEach(b=>b.addEventListener('click',()=>openView(b.dataset.view)));$('#back-home').addEventListener('click',()=>openView('home'));$('#reader-back').addEventListener('click',()=>openView('home'));$('#mobile-menu').addEventListener('click',()=>$('.sidebar').classList.toggle('is-open'));$('#logout-button').addEventListener('click',async()=>{clearInterval(communityTimer);await cloudAuth?.signOut();state.user=null;closeWord();switchAuth('login');showScreen('auth-screen')});$$('[data-speak]').forEach(b=>b.addEventListener('click',()=>{sound('tap');speak(b.dataset.speak)}));
