function renderModule(n){if(n==='quiz'){state.quizIndex=0;state.quizScore=0;renderQuiz();return}if(n==='wrongbook'){renderWrongbook();return}if(n==='chat'){renderChat();return}const[t,s,c]=moduleData[n]||moduleData.words;$('#module-content').innerHTML=`<div class="module-hero"><p class="eyebrow">${n.toUpperCase()} PRACTICE</p><h2>${t}</h2><p>${s}。内容已经根据你的 ${state.user?.level||'B1'} 水平进行调整。</p></div><div class="activity-grid">${c.map((x,i)=>`<article class="activity-card"><span class="pill">${String(i+1).padStart(2,'0')}</span><h3>${x}</h3><p>${i===0?'今天的推荐任务，完成后获得 20 XP。':'可随时开始，学习进度会自动保存。'}</p><button>${n==='video'?'▶ 播放':'开始练习'}</button></article>`).join('')}</div>`;$$('.activity-card button').forEach(b=>b.addEventListener('click',()=>{sound('success');b.textContent='✓ 已加入今日计划';b.style.background='#ef6f61'}))}
function renderQuiz(){const q=quizQuestions[state.quizIndex];state.quizLocked=false;$('#module-content').innerHTML=`<div class="module-hero"><p class="eyebrow">WORD CHALLENGE</p><h2>单词挑战</h2><p>每道题作答后都会显示完整单词解释；答错的词会自动进入错题本。</p></div><article class="activity-card quiz-box"><span class="pill">${state.quizIndex+1} / ${quizQuestions.length}</span><div class="quiz-word">${q.word}</div><p>${q.phonetic}</p><button class="quiz-sound audio-circle" aria-label="播放 ${q.word}">◖</button><div class="quiz-options">${q.options.map(o=>`<button data-quiz-option="${o}">${o}</button>`).join('')}</div><div id="quiz-explanation"></div></article>`;$('.quiz-sound').addEventListener('click',()=>speak(q.word));$$('[data-quiz-option]').forEach(b=>b.addEventListener('click',()=>answerQuiz(b.dataset.quizOption,b)))}
function answerQuiz(choice,button){if(state.quizLocked)return;state.quizLocked=true;const q=quizQuestions[state.quizIndex],ok=choice===q.answer;button.classList.add(ok?'correct':'wrong');$$('[data-quiz-option]').forEach(b=>{b.disabled=true;if(b.dataset.quizOption===q.answer)b.classList.add('correct-answer')});if(ok){state.quizScore++;sound('success');showXP(button)}else{sound('error');const a=wrongbook(),old=a.find(x=>x.word===q.word);if(old)old.count=(old.count||1)+1;else a.push({...q,count:1,addedAt:Date.now()});saveWrongbook(a)}$('#quiz-explanation').innerHTML=`<section class="quiz-feedback ${ok?'is-correct':'is-wrong'}"><div class="feedback-status">${ok?'✓ 回答正确':'✕ 回答错误'}</div><div class="feedback-word"><div><strong>${q.word}</strong><span>${q.phonetic}</span></div><button class="audio-circle" id="feedback-audio">◖</button></div><p class="feedback-meaning">${q.answer}｜${q.definition}</p><p class="feedback-example">${q.example}</p><button class="primary-button next-question" id="next-question">${state.quizIndex===quizQuestions.length-1?'查看成绩':'下一题'}<span>→</span></button></section>`;$('#feedback-audio').addEventListener('click',()=>speak(q.word));$('#next-question').addEventListener('click',nextQuiz)}
function nextQuiz(){if(state.quizIndex<quizQuestions.length-1){state.quizIndex++;sound('next');renderQuiz();return}$('#module-content').innerHTML=`<div class="module-hero"><p class="eyebrow">CHALLENGE COMPLETE</p><h2>完成本轮挑战</h2><p>你答对了 ${state.quizScore} / ${quizQuestions.length} 题，错题已经自动保存。</p></div><div class="quiz-summary"><strong>${state.quizScore*20}%</strong><h3>${state.quizScore===quizQuestions.length?'全部正确，太棒了！':'去错题本再巩固一次吧'}</h3><div><button class="primary-button" id="retry-quiz">重新挑战 <span>↻</span></button><button class="light-outline" id="open-wrongbook">查看错题本</button></div></div>`;$('#retry-quiz').addEventListener('click',()=>{state.quizIndex=0;state.quizScore=0;renderQuiz()});$('#open-wrongbook').addEventListener('click',()=>openView('wrongbook'))}
function showXP(el){const r=el.getBoundingClientRect(),x=document.createElement('span');x.className='xp-burst';x.textContent='+10 XP';x.style.left=`${r.left+r.width/2}px`;x.style.top=`${r.top}px`;document.body.append(x);setTimeout(()=>x.remove(),1000)}
function renderWrongbook(){const a=wrongbook();$('#module-content').innerHTML=`<div class="module-hero"><p class="eyebrow">REVIEW & IMPROVE</p><h2>错题本</h2><p>回顾做错的单词，查看解释并重新发音练习。</p></div>${a.length?`<div class="wrongbook-grid">${a.map((x,i)=>`<article class="wrong-card"><div class="wrong-top"><span>错 ${x.count||1} 次</span><button data-remove-wrong="${i}" aria-label="移除 ${x.word}">×</button></div><h3>${x.word}</h3><small>${x.phonetic}</small><p><strong>${x.answer}</strong> · ${x.definition}</p><blockquote>${x.example}</blockquote><button class="review-sound" data-review-speak="${x.word}">◖ 播放读音</button></article>`).join('')}</div>`:`<div class="empty-state"><span>✓</span><h3>错题本还是空的</h3><p>完成单词挑战后，答错的词会自动出现在这里。</p><button class="primary-button" id="start-quiz">开始单词挑战 <span>→</span></button></div>`}`;$$('[data-review-speak]').forEach(b=>b.addEventListener('click',()=>speak(b.dataset.reviewSpeak)));$$('[data-remove-wrong]').forEach(b=>b.addEventListener('click',()=>{const n=wrongbook();n.splice(Number(b.dataset.removeWrong),1);saveWrongbook(n);renderWrongbook()}));$('#start-quiz')?.addEventListener('click',()=>openView('quiz'))}
async function renderChat(){clearInterval(communityTimer);state.communityTab=state.communityTab||'feed';$('#module-content').innerHTML=`<div class="module-hero chat-hero"><p class="eyebrow">ENGLISH COMMUNITY</p><h2>英语学习社区</h2><p>公共动态与一对一私信都连接腾讯云；不同设备、不同账号可以真正交流。</p></div><div class="community-tabs"><button data-community-tab="feed" class="${state.communityTab==='feed'?'is-active':''}">公共动态</button><button data-community-tab="direct" class="${state.communityTab==='direct'?'is-active':''}">私信聊天</button></div><div id="community-content" class="community-content"><div class="cloud-loading">正在连接学习社区…</div></div>`;$$('[data-community-tab]').forEach(b=>b.addEventListener('click',()=>{state.communityTab=b.dataset.communityTab;renderChat()}));await refreshCommunity();communityTimer=setInterval(()=>{if($('#community-content'))refreshCommunity(true)},3500)}
async function refreshCommunity(silent=false){try{if(state.communityTab==='feed')await renderFeed();else await renderDirectMessages()}catch(error){console.error(error);if(!silent&&$('#community-content'))$('#community-content').innerHTML=`<div class="empty-state"><h3>暂时无法连接社区</h3><p>${escapeHtml(cloudError(error))}</p><button class="primary-button" id="retry-community">重新连接</button></div>`;$('#retry-community')?.addEventListener('click',()=>refreshCommunity())}}
async function getProfiles(){const {data,error}=await cloudDb.from('profiles').select('*').order('created_at',{ascending:true});if(error)throw error;cachedProfiles=data||[];return cachedProfiles}
async function renderFeed(){const [{data:posts,error:postError},profiles,{data:likes,error:likeError},{data:comments,error:commentError},{data:reposts,error:repostError}]=await Promise.all([cloudDb.from('posts').select('*').order('created_at',{ascending:false}).limit(50),getProfiles(),cloudDb.from('post_likes').select('*'),cloudDb.from('post_comments').select('*').order('created_at',{ascending:true}),cloudDb.from('post_reposts').select('*')]);if(postError||likeError||commentError||repostError)throw(postError||likeError||commentError||repostError);const names=Object.fromEntries(profiles.map(p=>[p.user_id,p]));$('#community-content').innerHTML=`<section class="feed-layout"><form class="post-composer" id="post-form"><div class="composer-head"><span class="contact-avatar">${escapeHtml((state.user.name||'我')[0])}</span><div><strong>${escapeHtml(state.user.name)}</strong><small>分享今天的英语学习</small></div></div><textarea id="post-content" maxlength="2000" placeholder="Write something in English… 也可以记录学习感受" required></textarea><div class="composer-actions"><label class="image-pick">＋ 添加图片<input id="post-image" type="file" accept="image/png,image/jpeg,image/webp,image/gif" /></label><span id="image-name">支持 JPG、PNG、WebP、GIF，最大 5MB</span><button type="submit">发布动态 ↗</button></div><p class="auth-message" id="post-message"></p></form><div class="feed-list">${(posts||[]).length?(posts||[]).map(post=>feedCard(post,names[post.author_id],likes||[],comments||[],reposts||[])).join(''):'<div class="empty-state"><h3>还没有动态</h3><p>成为第一个分享英语学习的人吧。</p></div>'}</div></section>`;$('#post-image').addEventListener('change',e=>{$('#image-name').textContent=e.target.files[0]?.name||'未选择图片'});$('#post-form').addEventListener('submit',createPost);$$('[data-like-post]').forEach(b=>b.addEventListener('click',()=>togglePostRelation('post_likes',b.dataset.likePost)));$$('[data-repost]').forEach(b=>b.addEventListener('click',()=>togglePostRelation('post_reposts',b.dataset.repost)));$$('[data-comment-toggle]').forEach(b=>b.addEventListener('click',()=>b.closest('.feed-card').classList.toggle('show-comments')));$$('.comment-form').forEach(f=>f.addEventListener('submit',createComment))}
function feedCard(post,profile,likes,comments,reposts){const postLikes=likes.filter(x=>x.post_id===post.id),postComments=comments.filter(x=>x.post_id===post.id),postReposts=reposts.filter(x=>x.post_id===post.id),mineLike=postLikes.some(x=>x.user_id===state.user.id),mineRepost=postReposts.some(x=>x.user_id===state.user.id),name=profile?.display_name||'学习者';return`<article class="feed-card"><header><span class="contact-avatar">${escapeHtml(name[0]||'L')}</span><div><strong>${escapeHtml(name)}</strong><small>${escapeHtml(profile?.english_level||'B1')} · ${new Date(post.created_at).toLocaleString('zh-CN')}</small></div></header><p class="post-copy">${escapeHtml(post.content).replace(/\n/g,'<br>')}</p>${(post.image_urls||[]).map(url=>`<img class="post-image" src="${escapeHtml(url)}" alt="动态图片" loading="lazy">`).join('')}<div class="post-actions"><button data-like-post="${post.id}" class="${mineLike?'is-active':''}">♥ ${postLikes.length}</button><button data-comment-toggle="${post.id}">◌ ${postComments.length}</button><button data-repost="${post.id}" class="${mineRepost?'is-active':''}">↻ ${postReposts.length}</button></div><div class="post-comments">${postComments.map(c=>{const p=profileById(c.author_id);return`<p><strong>${escapeHtml(p?.display_name||'学习者')}</strong> ${escapeHtml(c.content)}</p>`}).join('')}<form class="comment-form" data-post-id="${post.id}"><input maxlength="500" placeholder="写一条评论…" required><button>发送</button></form></div></article>`}
let cachedProfiles=[];function profileById(id){return cachedProfiles.find(p=>p.user_id===id)}
async function createPost(e){e.preventDefault();const button=e.currentTarget.querySelector('button[type="submit"]'),content=$('#post-content').value.trim(),file=$('#post-image').files[0],message=$('#post-message');button.disabled=true;try{let image_urls=[];if(file){if(file.size>5*1024*1024)throw new Error('图片不能超过 5MB。');const safe=file.name.replace(/[^a-zA-Z0-9._-]/g,'-'),path=`${state.user.id}/${Date.now()}-${safe}`,bucket=cloudApp.storage.from('social-images'),{error}=await bucket.upload(path,file,{contentType:file.type});if(error)throw error;const {data:urlData}=bucket.getPublicUrl(path);const url=urlData?.publicUrl||urlData?.publicURL||urlData?.url;if(!url)throw new Error('图片已上传，但未取得访问地址。');image_urls=[url]}const {error}=await cloudDb.from('posts').insert({author_id:state.user.id,content,image_urls});if(error)throw error;sound('success');await renderFeed()}catch(error){message.textContent=cloudError(error)}finally{button.disabled=false}}
async function togglePostRelation(table,postId){const {data,error}=await cloudDb.from(table).select('*').eq('post_id',postId).eq('user_id',state.user.id).maybeSingle();if(error)throw error;const result=data?await cloudDb.from(table).delete().eq('post_id',postId).eq('user_id',state.user.id):await cloudDb.from(table).insert({post_id:postId,user_id:state.user.id});if(result.error)throw result.error;await renderFeed()}
async function createComment(e){e.preventDefault();const input=e.currentTarget.querySelector('input'),content=input.value.trim(),post_id=e.currentTarget.dataset.postId;if(!content)return;const {error}=await cloudDb.from('post_comments').insert({post_id,author_id:state.user.id,content});if(error)throw error;await renderFeed()}
async function renderDirectMessages(){cachedProfiles=await getProfiles();const others=cachedProfiles.filter(p=>p.user_id!==state.user.id);if(!state.chatUserId&&others[0])state.chatUserId=others[0].user_id;const active=profileById(state.chatUserId);let messages=[];if(active){state.conversationId=await findOrCreateConversation(active.user_id,false);if(state.conversationId){const {data,error}=await cloudDb.from('messages').select('*').eq('conversation_id',state.conversationId).order('created_at',{ascending:true});if(error)throw error;messages=data||[]}}$('#community-content').innerHTML=`<div class="chat-shell"><aside class="chat-contacts"><div class="contact-heading"><strong>学习伙伴</strong><span>● 云端在线</span></div>${others.length?others.map(p=>`<button class="chat-contact ${p.user_id===state.chatUserId?'is-active':''}" data-direct-user="${p.user_id}"><span class="contact-avatar">${escapeHtml((p.display_name||'L')[0])}</span><span><strong>${escapeHtml(p.display_name)}</strong><small>${escapeHtml(p.english_level)} · 可私信</small></span></button>`).join(''):'<p class="no-contact">其他用户注册后会出现在这里。</p>'}</aside><section class="chat-panel"><header>${active?`<span class="contact-avatar">${escapeHtml((active.display_name||'L')[0])}</span><div><strong>${escapeHtml(active.display_name)}</strong><small>${escapeHtml(active.english_level)} · 私信加密传输</small></div>`:'<div><strong>等待学习伙伴加入</strong></div>'}</header><div class="chat-messages" id="chat-messages">${messages.map(m=>`<div class="chat-message ${m.sender_id===state.user.id?'is-mine':''}"><span class="message-avatar">${escapeHtml((profileById(m.sender_id)?.display_name||'L')[0])}</span><div><small>${escapeHtml(profileById(m.sender_id)?.display_name||'学习者')} · ${new Date(m.created_at).toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit'})}</small><p>${escapeHtml(m.content)}</p></div></div>`).join('')}</div>${active?'<form class="chat-compose" id="chat-form"><input id="chat-input" maxlength="2000" autocomplete="off" placeholder="用英语写一条私信…" required><button>发送 ↗</button></form>':''}</section></div>`;$$('[data-direct-user]').forEach(b=>b.addEventListener('click',()=>{state.chatUserId=b.dataset.directUser;state.conversationId=null;renderDirectMessages()}));$('#chat-form')?.addEventListener('submit',sendDirectMessage);const box=$('#chat-messages');if(box)box.scrollTop=box.scrollHeight}
async function findOrCreateConversation(otherId,create=true){const {data:mine,error}=await cloudDb.from('conversation_members').select('conversation_id,user_id').eq('user_id',state.user.id);if(error)throw error;const ids=(mine||[]).map(x=>x.conversation_id);if(ids.length){const {data:members,error:memberError}=await cloudDb.from('conversation_members').select('conversation_id,user_id').in('conversation_id',ids);if(memberError)throw memberError;const found=ids.find(id=>{const people=members.filter(x=>x.conversation_id===id).map(x=>x.user_id);return people.length===2&&people.includes(otherId)});if(found)return found}if(!create)return null;const {data:conversation,error:createError}=await cloudDb.from('conversations').insert({owner_id:state.user.id}).select('id').single();if(createError)throw createError;const {error:joinError}=await cloudDb.from('conversation_members').insert([{conversation_id:conversation.id,user_id:state.user.id},{conversation_id:conversation.id,user_id:otherId}]);if(joinError)throw joinError;return conversation.id}
async function sendDirectMessage(e){e.preventDefault();const input=$('#chat-input'),content=input.value.trim(),button=e.currentTarget.querySelector('button');if(!content)return;button.disabled=true;try{state.conversationId||=await findOrCreateConversation(state.chatUserId,true);const {error}=await cloudDb.from('messages').insert({conversation_id:state.conversationId,sender_id:state.user.id,content});if(error)throw error;input.value='';sound('next');await renderDirectMessages()}catch(error){alert(cloudError(error))}finally{button.disabled=false}}
function escapeHtml(v){return String(v).replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'})[c])}
function prepareClickableArticle(){$$('#reading-paper h3, #reading-paper p, #reading-paper blockquote').forEach(c=>{[...c.childNodes].forEach(n=>{if(n.nodeType!==Node.TEXT_NODE)return;const p=n.textContent.split(/([A-Za-z]+(?:'[A-Za-z]+)?)/g),f=document.createDocumentFragment();p.forEach(x=>{if(/^[A-Za-z]+(?:'[A-Za-z]+)?$/.test(x)){const b=document.createElement('button');b.type='button';b.className='word';b.dataset.word=x.toLowerCase();b.textContent=x;f.append(b)}else f.append(document.createTextNode(x))});n.replaceWith(f)})});$$('.word').forEach(b=>b.addEventListener('click',e=>{e.stopPropagation();openWord(b)}))}
function getWordData(w){if(wordNotes[w])return wordNotes[w];let m=basicMeanings[w];if(!m&&w.endsWith('s'))m=basicMeanings[w.slice(0,-1)];if(!m&&w.endsWith('ed'))m=basicMeanings[w.slice(0,-2)];if(!m&&w.endsWith('ing'))m=basicMeanings[w.slice(0,-3)];return{phonetic:'点击右侧按钮播放英式读音',meaning:m||'常用英语词汇；请结合当前句子理解',note:`在本文句子中，“${w}”与前后内容共同表达文章含义。`}}
function openWord(b){const w=b.dataset.word,d=getWordData(w);$('#popover-word').textContent=w;$('#popover-phonetic').textContent=d.phonetic;$('#popover-meaning').textContent=d.meaning;$('#popover-note').textContent=d.note;const p=$('#word-popover');p.classList.add('is-open');p.dataset.word=w;document.body.classList.add('word-open');sound('tap')}function closeWord(){$('#word-popover').classList.remove('is-open');document.body.classList.remove('word-open')}
$('#reading-paper').addEventListener('click',e=>{if(!e.target.closest('.word'))closeWord()});$('#popover-close').addEventListener('click',closeWord);$('#popover-audio').addEventListener('click',()=>speak($('#word-popover').dataset.word));document.addEventListener('keydown',e=>{if(e.key==='Escape')closeWord()});
prepareClickableArticle();bootstrapCloud();

