const videoTitleZh={
 'Hello and Introductions':'问候与自我介绍','Colours Around Us':'我们身边的颜色','Animals and Actions':'动物与动作','My Daily Routine':'我的日常生活','Food I Like':'我喜欢的食物','Family and Friends':'家人与朋友','Weather Words':'天气词汇','A Short English Story':'英语小故事','Sing and Learn Verbs':'唱歌学动词','My School Day':'我的校园生活',
 'Speak with Confidence':'自信表达','School Life Conversation':'校园生活对话','How to Learn Vocabulary':'怎样学习词汇','Social Media English':'社交媒体英语','Agreeing and Disagreeing':'表达同意与不同意','Teen News Listening':'青少年新闻听力','Pronunciation Challenge':'发音挑战','Study Habits':'学习习惯','Future Careers':'未来职业','Mini Debate Practice':'迷你辩论练习',
 'University Conversation':'大学生活对话','CET Listening Skills':'四级听力技巧','English Interview Practice':'英语面试练习','6 Minute English':'六分钟英语','IELTS Speaking Part 1':'雅思口语第一部分','Academic Vocabulary':'学术词汇','Presentation Skills':'演讲技巧','IELTS Listening Strategy':'雅思听力策略','Critical Thinking Talk':'批判性思维表达','Fluent Speaking Habits':'流利口语习惯',
 'Everyday Small Talk':'日常寒暄','English at Work':'职场英语','Business Email English':'商务邮件英语','Travel Conversation':'旅行对话','Meetings and Opinions':'会议与观点表达','News English Listening':'新闻英语听力','Professional Presentation':'专业演讲','Advanced Pronunciation':'高阶发音','Global Issues Discussion':'全球议题讨论','Confident Public Speaking':'自信公开演讲'
};
let videoSpeechRate=1;
function videoStudySegments(v){const zh=videoTitleZh[v.title]||v.title;return[
  {en:`Today's lesson focuses on ${v.title}.`,zh:`今天的课程主题是“${zh}”。`},
  {en:'Listen once for the main idea before reading the bilingual notes.',zh:'先完整听一遍抓住主旨，再阅读双语学习笔记。'},
  {en:'Notice the speaker’s pronunciation, sentence stress and linking.',zh:'注意说话者的发音、句子重音和连读。'},
  {en:'Pause after a useful expression and repeat it clearly in your own voice.',zh:'听到实用表达后暂停视频，并用自己的声音清晰跟读。'}
]}
function renderVideoTranscript(v){return`<section class="video-transcript"><div class="transcript-heading"><div><p class="eyebrow">BILINGUAL LISTENING</p><h3>双语精听文本</h3><small>学习版内容提要 · 点击任意一段播放英文</small></div><div class="speed-control" aria-label="朗读速度">${[.75,1,1.25,1.5].map(rate=>`<button data-speech-rate="${rate}" class="${rate===videoSpeechRate?'is-active':''}">${rate}×</button>`).join('')}</div></div><div class="transcript-list">${videoStudySegments(v).map((s,i)=>`<button class="transcript-line" data-transcript-text="${escapeHtml(s.en)}"><span>${String(i+1).padStart(2,'0')}</span><div><strong>${s.en}</strong><p>${s.zh}</p></div><i>◖</i></button>`).join('')}</div></section>`}
function speakVideoLine(text){if(!('speechSynthesis'in window))return;speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(text);u.lang='en-GB';u.rate=videoSpeechRate;speechSynthesis.speak(u)}
function bindVideoTranscript(){$$('[data-speech-rate]').forEach(b=>b.addEventListener('click',()=>{videoSpeechRate=Number(b.dataset.speechRate);$$('[data-speech-rate]').forEach(x=>x.classList.toggle('is-active',x===b));sound('tap')}));$$('[data-transcript-text]').forEach(b=>b.addEventListener('click',()=>{speakVideoLine(b.dataset.transcriptText);$$('[data-transcript-text]').forEach(x=>x.classList.toggle('is-playing',x===b))}))}

const articleTopics={
 kids:[['The Lost Red Kite','A1','A child follows a bright kite through the park and learns to ask for help.'],['A Day at the Zoo','A1','Mia visits the zoo and describes the animals she sees.'],['My Helpful Robot','A1','A small robot helps a family finish simple jobs at home.'],['The Rainy Picnic','A1','Friends change their plan and have a happy picnic indoors.'],['Sam Plants a Seed','A1','Sam learns what a plant needs to grow.'],['The Moon at Night','A2','A curious child observes how the moon seems to change.'],['A New Student','A2','The class welcomes a new student from another country.'],['The Little Library','A2','Children build a book-sharing box for their neighbourhood.'],['Saving Water','A2','A family finds five easy ways to use less water.'],['The Weekend Adventure','A2','Two friends follow a map and solve a simple mystery.']],
 teens:[['Why Habits Matter','B1','Small repeated actions can shape learning and confidence over time.'],['The Science of Music','B1','Music affects memory, mood and the way people connect.'],['A Week Without Social Media','B1','A student records what changes after turning off social apps.'],['Learning from Failure','B1','Mistakes can become useful information rather than final results.'],['Cities for Young People','B1','Good public spaces help teenagers learn, move and meet safely.'],['The Future of School','B2','Technology may change classrooms, but human guidance still matters.'],['Should Homework Change?','B2','Students compare the value of practice, projects and free time.'],['Fast Fashion Choices','B2','Clothing decisions connect personal style with global impacts.'],['How Sleep Supports Learning','B2','Sleep helps the brain organise memories and control attention.'],['Finding Your Voice','B2','Clear speaking begins with ideas, practice and respect for listeners.']],
 young:[['The Attention Economy','B1','Digital services compete for attention and shape daily decisions.'],['Learning Beyond University','B1','Career growth increasingly depends on continuous learning.'],['Remote Work and Community','B2','Flexible work creates freedom but also new social challenges.'],['Why Languages Change','B2','Words, accents and grammar evolve as communities interact.'],['The Psychology of Choice','B2','Too many options can make even simple decisions difficult.'],['Rethinking Productivity','B2','Useful work depends on energy, priorities and recovery.'],['AI and Creative Work','C1','New tools are changing how people create, judge and collaborate.'],['Urban Life in 2050','C1','Future cities must balance growth, climate and quality of life.'],['What Makes Evidence Strong?','C1','Reliable conclusions require careful sources and transparent reasoning.'],['The Value of Deep Reading','C1','Sustained reading develops patience, inference and complex understanding.']],
 adults:[['The Art of Small Talk','A2','Simple questions can open comfortable and useful conversations.'],['Building a Learning Routine','B1','A realistic schedule makes language practice easier to maintain.'],['Communication at Work','B1','Clear expectations reduce mistakes and improve cooperation.'],['Travel with Confidence','B1','Preparation and flexible language help travellers solve problems.'],['Making Better Decisions','B2','Good decisions combine evidence, values and awareness of uncertainty.'],['Lifelong Brain Health','B2','Sleep, movement and learning all contribute to cognitive health.'],['Leading Through Change','B2','Trust and communication help teams adapt to uncertainty.'],['The Future of Careers','C1','Longer working lives may require repeated reinvention.'],['Global Citizenship','C1','Local choices are increasingly connected to global systems.'],['Technology and Human Connection','C1','Digital tools can strengthen or weaken relationships depending on use.']]
};
function articleBody(item){return[`<p>${item[2]} The topic is introduced through a clear situation and several practical details suitable for ${item[1]} learners.</p>`,`<p>As you read, notice how the writer connects examples with the main idea. Try to identify useful vocabulary, then explain the article in your own English.</p>`,`<p>Reflection: What is one idea from this article that you could apply to your own life or studies?</p>`].join('')}

function renderVideoLibrary(){const selected=ageKeys[state.user?.age]||'young',items=videoItems(selected);$('#module-content').innerHTML=`<div class="module-hero"><p class="eyebrow">VIDEO LIBRARY</p><h2>分级视频学习</h2><p>四个年龄段各10个视频课程，全部使用中国大陆可访问的视频源，并在本站播放器中直接播放。</p></div><div class="content-tabs">${Object.entries(ageLabels).map(([k,v])=>`<button data-video-age="${k}" class="${k===selected?'is-active':''}">${v}<small>10个视频</small></button>`).join('')}</div><section class="video-player-card"><div class="video-frame"><iframe id="lesson-video" src="${bilibiliEmbed(items[0])}" title="${items[0].title}" loading="lazy" sandbox="allow-scripts allow-same-origin allow-forms allow-presentation" referrerpolicy="strict-origin-when-cross-origin" allow="autoplay; fullscreen; picture-in-picture" allowfullscreen></iframe></div><div><span id="video-level">${items[0].level}</span><h3 id="video-title">${items[0].title}</h3><p>视频将在本站内播放，不会把当前页面跳转到其他网站。</p><small class="video-source" id="video-source">来源：${items[0].source} · 大陆可播放</small></div></section><div id="video-transcript-wrap">${renderVideoTranscript(items[0])}</div><div class="media-grid" id="video-grid">${renderVideoCards(items)}</div>`;bindVideoLibrary()}
function renderVideoCards(items){return items.map((v,i)=>`<button class="media-card ${i===0?'is-active':''}" data-video-index="${i}" data-video-bvid="${v.bvid}" data-video-page="${v.page}" data-video-source="${v.source}" data-video-title="${v.title}" data-video-level="${v.level}"><span class="media-number">${String(i+1).padStart(2,'0')}</span><strong>${v.title}</strong><small>${v.level} · ${v.duration}</small><i>▶</i></button>`).join('')}
function bindVideoLibrary(){$$('[data-video-age]').forEach(b=>b.addEventListener('click',()=>{const key=b.dataset.videoAge,items=videoItems(key);$$('[data-video-age]').forEach(x=>x.classList.toggle('is-active',x===b));$('#video-grid').innerHTML=renderVideoCards(items);selectVideo(items[0],0);bindVideoCards()}));bindVideoCards();bindVideoTranscript()}
function bindVideoCards(){$$('[data-video-index]').forEach(b=>b.addEventListener('click',()=>selectVideo({bvid:b.dataset.videoBvid,page:Number(b.dataset.videoPage),source:b.dataset.videoSource,title:b.dataset.videoTitle,level:b.dataset.videoLevel},Number(b.dataset.videoIndex))))}
function selectVideo(v,index){window.speechSynthesis?.cancel?.();$('#lesson-video').src=bilibiliEmbed(v);$('#lesson-video').title=v.title;$('#video-title').textContent=v.title;$('#video-level').textContent=v.level;$('#video-source').textContent=`来源：${v.source} · 大陆可播放`;$('#video-transcript-wrap').innerHTML=renderVideoTranscript(v);bindVideoTranscript();$$('[data-video-index]').forEach((b,i)=>b.classList.toggle('is-active',i===index));sound('tap')}

function renderArticleLibrary(){const selected=ageKeys[state.user?.age]||'young';$('#module-content').innerHTML=`<div class="module-hero"><p class="eyebrow">READING LIBRARY</p><h2>分级英文读物</h2><p>四个年龄段各10篇文章，难度从 A1 到 C1；系统已选中最适合你的分类。</p></div><div class="content-tabs">${Object.entries(ageLabels).map(([k,v])=>`<button data-article-age="${k}" class="${k===selected?'is-active':''}">${v}<small>10篇文章</small></button>`).join('')}</div><div class="article-library-grid" id="article-library-grid">${renderArticleCards(selected)}</div><div class="article-modal" id="article-modal"><button id="article-close">×</button><span id="article-modal-level"></span><h2 id="article-modal-title"></h2><div id="article-modal-body"></div></div>`;bindArticleLibrary(selected)}
function renderArticleCards(age){return articleTopics[age].map((a,i)=>`<button class="article-library-card" data-article-index="${i}"><span>${String(i+1).padStart(2,'0')} · ${a[1]}</span><h3>${a[0]}</h3><p>${a[2]}</p><strong>开始阅读 →</strong></button>`).join('')}
function bindArticleLibrary(initial){let age=initial;$$('[data-article-age]').forEach(b=>b.addEventListener('click',()=>{age=b.dataset.articleAge;$$('[data-article-age]').forEach(x=>x.classList.toggle('is-active',x===b));$('#article-library-grid').innerHTML=renderArticleCards(age);bindArticleCards(age)}));bindArticleCards(age);$('#article-close').addEventListener('click',()=>$('#article-modal').classList.remove('is-open'))}
function bindArticleCards(age){$$('[data-article-index]').forEach(b=>b.addEventListener('click',()=>{const a=articleTopics[age][Number(b.dataset.articleIndex)];$('#article-modal-level').textContent=a[1]+' · '+ageLabels[age];$('#article-modal-title').textContent=a[0];$('#article-modal-body').innerHTML=articleBody(a);$('#article-modal').classList.add('is-open');sound('tap')}))}

function renderVocabularyLibrary(){const selected=recommendedBand();$('#module-content').innerHTML=`<div class="module-hero"><p class="eyebrow">VOCABULARY PATH</p><h2>分级词汇库</h2><p>包含初中、高中、四级、六级和雅思词汇；已根据你的年龄和 ${state.user?.level||'B1'} 水平推荐“${bandLabels[selected]}”。</p></div><div class="content-tabs word-band-tabs">${Object.entries(bandLabels).map(([k,v])=>`<button data-word-band="${k}" class="${k===selected?'is-active':''}">${v}<small>${wordBands[k].length}个精选词</small></button>`).join('')}</div><div class="vocabulary-grid" id="vocabulary-grid">${renderVocabularyCards(selected)}</div>`;$$('[data-word-band]').forEach(b=>b.addEventListener('click',()=>{const band=b.dataset.wordBand;$$('[data-word-band]').forEach(x=>x.classList.toggle('is-active',x===b));$('#vocabulary-grid').innerHTML=renderVocabularyCards(band);bindVocabularyCards()}));bindVocabularyCards()}
function renderVocabularyCards(band){return wordBands[band].map(word=>{const e=window.WORD_DATABASE?.[word]||{meaning:basicMeanings[word]||'常用词汇',phonetic:'暂无音标',part:'英文单词'};return`<article class="vocabulary-card"><div><span>${bandLabels[band]}</span><button class="mini-sound" data-vocab-speak="${word}">◖</button></div><h3>${word}</h3><small>${e.phonetic}</small><ol>${meaningsFor(e).slice(0,3).map(m=>`<li>${m}</li>`).join('')}</ol><blockquote>${wordExample(word,band)}</blockquote></article>`}).join('')}
function bindVocabularyCards(){$$('[data-vocab-speak]').forEach(b=>b.addEventListener('click',()=>speak(b.dataset.vocabSpeak)))}

const originalRenderModule=renderModule;
renderModule=function(name){if(name==='video'){renderVideoLibrary();return}if(name==='reading'){renderArticleLibrary();return}if(name==='words'){renderVocabularyLibrary();return}originalRenderModule(name)};

// Learning experience redesign: proficiency-first reading, one video template and quiz-led vocabulary.
const proficiencyLevels=['A1','A2','B1','B2','C1','C2'];
const proficiencyCopy={A1:'入门',A2:'基础',B1:'中级',B2:'中高级',C1:'高级',C2:'熟练'};
const readingSeed={
 A1:[['My Morning Routine','日常生活','A learner describes a simple morning routine before school.'],['The Red Bicycle','生活故事','A child finds a red bicycle and learns how to ride it.'],['A Visit to the Park','自然与生活','Two friends notice birds, flowers and changing weather.'],['My Helpful Family','家庭','A family works together to prepare dinner.'],['The New Classroom','校园','A new student meets classmates and learns their names.'],['A Small Garden','自然','Mia plants three seeds and watches them grow.']],
 A2:[['A Weekend Adventure','旅行','Two friends follow a map and solve a small problem.'],['The Little Library','社区','Neighbours build a book-sharing box for their street.'],['Learning a New Skill','成长','Regular practice helps a learner become more confident.'],['Saving Water at Home','环境','A family discovers practical ways to use less water.'],['The Friendly Café','日常交流','A visitor orders food and starts a friendly conversation.'],['Why We Need Sleep','健康','Simple habits can make rest more regular and useful.']],
 B1:[['Why Habits Matter','成长与学习','Small repeated actions can shape learning and confidence over time.'],['The Science of Music','科学与文化','Music affects memory, mood and the way people connect.'],['A Week Without Social Media','科技生活','A student records what changes after turning off social apps.'],['Learning from Failure','成长','Mistakes can become useful information rather than final results.'],['Cities for Young People','城市生活','Good public spaces help people learn, move and meet safely.'],['The Attention Economy','科技生活','Digital services compete for attention and influence daily decisions.']],
 B2:[['The Future of School','教育','Technology may change classrooms, but human guidance still matters.'],['Fast Fashion Choices','社会与环境','Clothing decisions connect personal style with global impacts.'],['How Sleep Supports Learning','健康与科学','Sleep helps the brain organise memories and control attention.'],['Why Languages Change','语言','Words, accents and grammar evolve as communities interact.'],['The Psychology of Choice','心理学','Too many options can make even simple decisions difficult.'],['Remote Work and Community','工作','Flexible work creates freedom but also new social challenges.']],
 C1:[['AI and Creative Work','科技与文化','New tools are changing how people create, judge and collaborate.'],['What Makes Evidence Strong?','学术思维','Reliable conclusions require careful sources and transparent reasoning.'],['The Value of Deep Reading','阅读与思维','Sustained reading develops patience, inference and complex understanding.'],['Urban Life in 2050','未来城市','Future cities must balance growth, climate and quality of life.'],['Technology and Human Connection','社会','Digital tools can strengthen or weaken relationships depending on use.'],['Global Citizenship','全球议题','Local choices are increasingly connected to global systems.']],
 C2:[['The Ethics of Persuasion','语言与社会','Persuasive language can clarify public choices while also concealing unequal power.'],['Memory, Identity and Narrative','人文思考','Personal memories are repeatedly reconstructed through language and social context.'],['Uncertainty in Public Debate','批判思维','Responsible argument distinguishes incomplete evidence from deliberate ambiguity.'],['The Architecture of Attention','社会与科技','Modern environments shape attention through subtle incentives and repeated interruption.'],['When Metaphors Govern Thought','语言学','Metaphors do more than decorate speech; they influence the categories people use.'],['Progress and Its Discontents','社会思想','Accounts of progress often reveal competing assumptions about value, justice and time.']]
};
function buildArticleParagraphs(article,level){const[title,topic,summary]=article,targets={A1:150,A2:280,B1:560,B2:850,C1:1200,C2:1650},target=targets[level]||560;const simple=[`${summary} The story begins on an ordinary day. A person notices something new and decides to learn more about it.`,`At first, the task looks difficult. The main character stops, thinks, and asks a clear question. This small step makes the next action easier.`,`Other people offer help and share what they know. They listen carefully, use simple words, and work together instead of giving up.`,`A mistake happens, but it is not the end of the story. The mistake shows everyone what needs to change, so they try again with a better plan.`,`Small details become important. A sound, a colour, a short message, or a friendly action helps the group understand the situation.`,`By the end of the day, the problem is smaller. The people have learned that regular practice, patience, and kindness can lead to real progress.`];const ideas=['individual experience','family and friendship','school and work','technology','health and daily habits','the natural environment','community life','fairness and opportunity','language and culture','evidence and measurement','short-term choices','long-term consequences','different generations','public policy','personal responsibility','cooperation across groups','unexpected costs','creative solutions','historical change','future possibilities'];const frames=[`A useful way to examine {idea} is to compare what people expect with what actually happens. Expectations shape attention, while experience provides details that may confirm or challenge the first impression. In the context of ${title.toLowerCase()}, this comparison helps readers separate a confident claim from an observation supported by evidence.`,`The role of {idea} also deserves attention. People do not make decisions in isolation: they respond to available information, social pressure, limited time, and the resources around them. Recognising these conditions does not remove responsibility, but it produces a more accurate explanation of why reasonable people may reach different conclusions.`,`From the perspective of {idea}, the central question is not simply whether change is good or bad. Readers must ask who benefits, who carries the cost, how quickly the effects appear, and whether the result can be reversed. These questions turn a general opinion into a structured piece of reasoning.`,`Evidence about {idea} should be interpreted carefully. A striking example may illustrate a pattern without proving that the pattern is universal. Strong readers compare several cases, notice missing information, and remain willing to revise their judgement when a clearer explanation becomes available.`];let paragraphs=[`${summary} This article examines ${title.toLowerCase()} as a question connected to ${topic.toLowerCase()}, everyday choices, and the wider systems in which those choices take place.`];if(level==='A1'||level==='A2'){for(const p of simple){paragraphs.push(p);if(paragraphs.join(' ').split(/\s+/).length>=target)break}while(paragraphs.join(' ').split(/\s+/).length<target)paragraphs.push(simple[paragraphs.length%simple.length]);return paragraphs}let i=0;while(paragraphs.join(' ').split(/\s+/).length<target){const idea=ideas[i%ideas.length],frame=frames[Math.floor(i/ideas.length)%frames.length].replace('{idea}',idea);paragraphs.push(frame);i++}paragraphs.push(`The most responsible conclusion is therefore provisional rather than weak. It connects the available evidence to a clear judgement, acknowledges reasonable counterarguments, and identifies what new information could change that judgement. Reading in this way turns ${title.toLowerCase()} from a fixed answer into a disciplined method of inquiry.`);return paragraphs}
function wordButtons(text,context){return String(text).split(/([A-Za-z]+(?:[’'][A-Za-z]+)?)/g).map(part=>/^[A-Za-z]/.test(part)?`<button class="reader-word" data-reader-word="${escapeHtml(part.toLowerCase().replace(/^[^a-z]+|[^a-z]+$/g,''))}" data-reader-context="${escapeHtml(context)}">${part}</button>`:escapeHtml(part)).join('')}
function renderLevelReading(){const selected=proficiencyLevels.includes(state.user?.level)?state.user.level:'B1';$('#module-content').innerHTML=`<div class="module-hero compact-hero"><p class="eyebrow">READ BY LEVEL</p><h2>分级英文阅读</h2><p>不按年龄划分。系统推荐 ${selected}，你可以自由切换 A1–C2；英文读物和精细阅读已合并。</p></div><div class="content-tabs level-tabs">${proficiencyLevels.map(l=>`<button data-reading-level="${l}" class="${l===selected?'is-active':''}"><strong>${l}</strong><small>${proficiencyCopy[l]}</small></button>`).join('')}</div><div class="level-reading-grid" id="level-reading-grid"></div>`;renderReadingCards(selected);$$('[data-reading-level]').forEach(b=>b.addEventListener('click',()=>{$$('[data-reading-level]').forEach(x=>x.classList.toggle('is-active',x===b));renderReadingCards(b.dataset.readingLevel)}))}
function renderReadingCards(level){const target={A1:150,A2:280,B1:560,B2:850,C1:1200,C2:1650}[level],grid=$('#level-reading-grid');grid.innerHTML=readingSeed[level].map((a,i)=>`<button class="level-reading-card" data-level-article="${i}" data-level="${level}"><span>${level} · ${a[1]}</span><h3>${a[0]}</h3><p>${a[2]}</p><footer><small>约 ${target} 词 · ${Math.ceil(target/100)} 分钟</small><strong>进入精读 →</strong></footer></button>`).join('');$$('[data-level-article]').forEach(b=>b.addEventListener('click',()=>openLevelArticle(b.dataset.level,Number(b.dataset.levelArticle))))}
function openLevelArticle(level,index){const article=readingSeed[level][index],paragraphs=buildArticleParagraphs(article,level),count=paragraphs.join(' ').split(/\s+/).length;$('#module-content').innerHTML=`<div class="level-reader" id="level-reader"><div class="reader-commandbar"><button class="back-button" id="reading-library-back">← 返回 ${level} 文章</button><div><span>${level} · ${proficiencyCopy[level]}</span><strong>${count} 词 · 约 ${Math.max(3,Math.ceil(count/80))} 分钟</strong></div></div><div class="reader-article-shell"><article class="reader-document"><p class="eyebrow">${article[1].toUpperCase()}</p><h1>${wordButtons(article[0],article[0])}</h1><p class="reader-instruction">点击标题或正文中的任意英文单词，查看音标、发音、多个词义和本文含义。</p>${paragraphs.map(p=>`<p>${wordButtons(p,p)}</p>`).join('')}</article><aside class="reader-word-panel" id="reader-word-panel" aria-live="polite"><button id="reader-word-close" aria-label="关闭">×</button><p class="eyebrow">WORD IN CONTEXT</p><div id="reader-word-content"><p>点击文章中的一个单词开始精读。</p></div></aside></div></div>`;$('#reading-library-back').addEventListener('click',renderLevelReading);$('#reader-word-close').addEventListener('click',closeReaderWord);$$('[data-reader-word]').forEach(b=>b.addEventListener('click',e=>{e.stopPropagation();openReaderWord(b.dataset.readerWord,b.dataset.readerContext,article[0])}));$('#level-reader').addEventListener('click',e=>{if(!e.target.closest('.reader-word-panel')&&!e.target.closest('.reader-word'))closeReaderWord()})}
function readerMeanings(entry){let list=meaningsFor(entry);const extras=['常见搭配中的延伸含义','在不同语境中的相关表达','该词的补充用法'];for(const x of extras)if(list.length<5)list.push(x);return list.slice(0,5)}
function openReaderWord(word,context,title){const entry=window.WORD_DATABASE?.[word]||{phonetic:'暂无音标',part:'英文单词',meaning:basicMeanings[word]||'请结合上下文理解'};const meanings=readerMeanings(entry);$('#reader-word-content').innerHTML=`<div class="reader-word-title"><div><h3>${word}</h3><span>${entry.phonetic||'暂无音标'} · ${entry.part||'英文单词'}</span></div><button class="audio-circle" id="reader-word-audio">◖</button></div><ol>${meanings.map(m=>`<li>${m}</li>`).join('')}</ol><div class="context-definition"><small>在这篇文章中</small><p>这里主要表示“${meanings[0].replace(/^[a-z.\s]+/i,'')}”，用于理解《${title}》中的这句话：</p><blockquote>${context}</blockquote></div>`;$('#level-reader').classList.add('has-word-popup');$('#reader-word-audio').addEventListener('click',()=>speak(word))}
function closeReaderWord(){$('#level-reader')?.classList.remove('has-word-popup')}

const transcriptTemplate=[
 {s:4.19,e:8.19,en:'No, no, no, no...',zh:'不，不，不，不……'},
 {s:8.21,e:16.24,en:"Attention, photons. Prepare to measure Earth's changing ice.",zh:'注意，光子们。准备测量地球不断变化的冰层。'},
 {s:16.26,e:32.45,en:'Laser pulse 22A4 departs in five, four, three, two, one.',zh:'激光脉冲22A4将在五、四、三、二、一后出发。'},
 {s:125.70,e:129.70,en:'Excellent job, Pho. Your travel time has been recorded.',zh:'干得漂亮，Pho。你的旅行时间已经记录。'},
 {s:129.72,e:133.77,en:"Let's add it to the elevation dataset.",zh:'让我们把它加入高程数据集。'},
 {s:133.79,e:137.79,en:'Ready the next group!',zh:'下一组准备！'}
];
let templateClipEnd=null;
function renderVideoTemplate(){const level=state.user?.level||'B1';$('#module-content').innerHTML=`<div class="module-hero compact-hero"><p class="eyebrow">VIDEO LAB TEMPLATE</p><h2>视频精听模板</h2><p>完整视频库将按 A1–C2 分级。现在先用一个 2分48秒的纯英文公开视频，确认逐句原声精听的交互方式。</p></div><section class="video-lab"><div class="video-lab-player"><video id="template-video" controls preload="metadata" playsinline><source src="https://svs.gsfc.nasa.gov/vis/a010000/a012500/a012525/PHOTONJUMPICESat2_prores.webm" type="video/webm"></video><div class="video-lab-meta"><div><span>A2 · 2:48</span><h3>Photon Jump</h3><p>NASA/SCAD 公共领域英语短片 · 模板视频</p></div><button id="template-play-toggle">▶ 播放 / 暂停</button></div><div class="video-speed-row"><span>视频速度</span>${[.75,1,1.25,1.5].map(r=>`<button data-video-rate="${r}" class="${r===1?'is-active':''}">${r}×</button>`).join('')}</div></div><aside class="synced-transcript"><div class="transcript-panel-head"><div><p class="eyebrow">TIMED TRANSCRIPT</p><h3>逐句原声精听</h3></div><small>点击句子，视频跳到对应时间并播放原声</small></div><div class="timed-lines">${transcriptTemplate.map((c,i)=>`<button class="timed-line" data-cue-index="${i}"><span>${formatVideoTime(c.s)}</span><div><strong>${c.en}</strong><p>${c.zh}</p></div><i>▶</i></button>`).join('')}</div></aside></section><div class="template-note"><strong>模板说明</strong><p>这个模板使用可直接控制的 HTML5 视频和真实时间轴。以后导入有授权的视频与字幕文件，就可以用同样方式扩展为 A1–C2 完整视频库。</p></div>`;bindVideoTemplate()}
function formatVideoTime(seconds){const m=Math.floor(seconds/60),s=Math.floor(seconds%60);return`${String(m).padStart(2,'0')}:${String(s).padStart(2,'0')}`}
function bindVideoTemplate(){const video=$('#template-video');$('#template-play-toggle').addEventListener('click',()=>video.paused?video.play():video.pause());$$('[data-video-rate]').forEach(b=>b.addEventListener('click',()=>{video.playbackRate=Number(b.dataset.videoRate);$$('[data-video-rate]').forEach(x=>x.classList.toggle('is-active',x===b))}));$$('[data-cue-index]').forEach(b=>b.addEventListener('click',()=>{const cue=transcriptTemplate[Number(b.dataset.cueIndex)];templateClipEnd=cue.e;video.currentTime=cue.s;video.play();highlightVideoCue(Number(b.dataset.cueIndex))}));video.addEventListener('timeupdate',()=>{const i=transcriptTemplate.findIndex(c=>video.currentTime>=c.s&&video.currentTime<c.e);if(i>=0)highlightVideoCue(i);if(templateClipEnd&&video.currentTime>=templateClipEnd){video.pause();templateClipEnd=null}});video.addEventListener('pause',()=>$('#template-play-toggle').textContent='▶ 播放');video.addEventListener('play',()=>$('#template-play-toggle').textContent='Ⅱ 暂停')}
function highlightVideoCue(index){$$('[data-cue-index]').forEach((b,i)=>b.classList.toggle('is-active',i===index));const active=$(`[data-cue-index="${index}"]`);active?.scrollIntoView?.({block:'nearest',behavior:'smooth'})}

let learningSession=null;
function renderWordLearning(){const recommended=recommendedBand();$('#module-content').innerHTML=`<div class="module-hero compact-hero"><p class="eyebrow">VOCABULARY SESSION</p><h2>单词学习</h2><p>背诵和考试已经合并。先设置词库与本轮目标，然后一次学习一个词，不再铺满整张词表。</p></div><form class="word-setup-card" id="word-setup-form"><div class="word-setup-intro"><span>Aa</span><div><h3>设置本轮学习</h3><p>系统推荐“${bandLabels[recommended]}”，但你可以自由选择其他词库。</p></div></div><div class="word-setup-fields"><label>词库<select id="study-bank">${Object.entries(bandLabels).map(([k,v])=>`<option value="${k}" ${k===recommended?'selected':''}>${v}</option>`).join('')}</select></label><label>英语等级<select id="study-level">${proficiencyLevels.map(l=>`<option ${l===(state.user?.level||'B1')?'selected':''}>${l} · ${proficiencyCopy[l]}</option>`).join('')}</select></label><label>学习状态<select id="study-mode"><option value="mixed">新词＋复习</option><option value="new">优先学习新词</option><option value="review">优先复习错词</option></select></label><label>本轮词数<select id="study-count"><option>10</option><option>20</option><option>30</option><option>40</option></select></label></div><button class="primary-button" type="submit">开始单词测试 <span>→</span></button></form><section class="learning-method"><p class="eyebrow">HOW IT WORKS</p><div><span>01</span><p><strong>先判断</strong><small>先看单词并选择正确含义。</small></p><span>02</span><p><strong>再理解</strong><small>无论对错都查看词义、音标和例句。</small></p><span>03</span><p><strong>自动复习</strong><small>错误和不认识的词自动进入错题本。</small></p></div></section>`;$('#word-setup-form').addEventListener('submit',startWordSession)}
function startWordSession(e){e.preventDefault();const bank=$('#study-bank').value,count=Number($('#study-count').value),mode=$('#study-mode').value;let words=[...wordBands[bank]];if(mode==='review'){const saved=wrongbook().map(x=>x.word).filter(w=>words.includes(w));words=[...saved,...words.filter(w=>!saved.includes(w))]}learningSession={bank,mode,words:words.slice(0,count),index:0,score:0,locked:false};renderWordQuestion()}
function vocabEntry(word){return window.WORD_DATABASE?.[word]||{meaning:basicMeanings[word]||'常用英语词汇',phonetic:'暂无音标',part:'英文单词'}}
function firstMeaning(word){return readerMeanings(vocabEntry(word))[0].replace(/^[a-z.\s]+/i,'')}
function renderWordQuestion(){if(learningSession.index>=learningSession.words.length){renderWordResult();return}const word=learningSession.words[learningSession.index],entry=vocabEntry(word),pool=wordBands[learningSession.bank].filter(w=>w!==word),distractors=[pool[(learningSession.index*3+5)%pool.length],pool[(learningSession.index*5+11)%pool.length],pool[(learningSession.index*7+17)%pool.length]],correct=firstMeaning(word),options=[correct,...distractors.map(firstMeaning)].sort(()=>Math.random()-.5);learningSession.locked=false;learningSession.correct=correct;$('#module-content').innerHTML=`<div class="word-session-top"><button class="back-button" id="leave-word-session">← 结束本轮</button><div><span>${bandLabels[learningSession.bank]}</span><strong>${learningSession.index+1} / ${learningSession.words.length}</strong></div></div><article class="single-word-quiz"><div class="word-progress"><i style="width:${(learningSession.index+1)/learningSession.words.length*100}%"></i></div><span class="quiz-label">选择最符合的中文意思</span><h2>${word}</h2><p>${entry.phonetic||'暂无音标'} · ${entry.part||'英文单词'}</p><button class="audio-circle large-audio" id="study-word-audio">◖</button><div class="single-word-options">${options.map(o=>`<button data-study-option="${escapeHtml(o)}">${o}</button>`).join('')}</div><button class="dont-know-button" id="dont-know-word">不认识，直接看解释</button><div id="word-answer-panel"></div></article>`;$('#leave-word-session').addEventListener('click',renderWordLearning);$('#study-word-audio').addEventListener('click',()=>speak(word));$$('[data-study-option]').forEach(b=>b.addEventListener('click',()=>answerStudyWord(b.dataset.studyOption,b)));$('#dont-know-word').addEventListener('click',()=>answerStudyWord('',null))}
function answerStudyWord(choice,button){if(learningSession.locked)return;learningSession.locked=true;const word=learningSession.words[learningSession.index],entry=vocabEntry(word),correct=choice===learningSession.correct;if(correct){learningSession.score++;button?.classList.add('correct');sound('success')}else{button?.classList.add('wrong');sound('error');const saved=wrongbook(),old=saved.find(x=>x.word===word),record={word,phonetic:`${entry.phonetic||'暂无音标'} · ${entry.part||'英文单词'}`,answer:learningSession.correct,definition:readerMeanings(entry).join('；'),example:wordExample(word,learningSession.bank),options:[],count:1,addedAt:Date.now()};if(old)old.count=(old.count||1)+1;else saved.push(record);saveWrongbook(saved)}$$('[data-study-option]').forEach(b=>{b.disabled=true;if(b.dataset.studyOption===learningSession.correct)b.classList.add('correct-answer')});const meanings=readerMeanings(entry);$('#word-answer-panel').innerHTML=`<section class="study-explanation ${correct?'is-correct':'is-wrong'}"><strong>${correct?'✓ 回答正确':'需要再复习'}</strong><h3>${word}</h3><ol>${meanings.map(m=>`<li>${m}</li>`).join('')}</ol><blockquote>${wordExample(word,learningSession.bank)}</blockquote><button class="primary-button" id="next-study-word">${learningSession.index===learningSession.words.length-1?'查看结果':'下一个单词'} <span>→</span></button></section>`;$('#next-study-word').addEventListener('click',()=>{learningSession.index++;renderWordQuestion()})}
function renderWordResult(){$('#module-content').innerHTML=`<div class="module-hero"><p class="eyebrow">SESSION COMPLETE</p><h2>本轮学习完成</h2><p>你答对了 ${learningSession.score} / ${learningSession.words.length} 个单词；错误和不认识的词已经保存到错题本。</p></div><div class="word-result-card"><strong>${Math.round(learningSession.score/learningSession.words.length*100)}%</strong><h3>${learningSession.score===learningSession.words.length?'全部掌握，完成得很好！':'复习错误词后再挑战一次'}</h3><div><button class="primary-button" id="restart-word-session">重新测试 <span>↻</span></button><button class="light-outline" id="return-word-setup">调整学习设置</button></div></div>`;$('#restart-word-session').addEventListener('click',()=>{learningSession.index=0;learningSession.score=0;renderWordQuestion()});$('#return-word-setup').addEventListener('click',renderWordLearning)}

renderModule=function(name){if(name==='reading'||name==='intensive'){renderLevelReading();return}if(name==='video'){renderVideoTemplate();return}if(name==='words'||name==='quiz'){renderWordLearning();return}originalRenderModule(name)};
